test_setup_files.tests/dates_test.rs:
use busdays::add_business_days;

// epoch_day 0 = 1970-01-01 (Thursday).
// 2024-05-31 (Friday) = 19874; 2024-06-03 (Monday) = 19877.
// 2024-05-27 (Monday) = 19870.
// 2024-06-01 (Saturday) = 19875.
// 2024-12-27 (Friday) = 20084; 2025-01-01 (Wednesday) = 20089.

#[test]
fn zero_returns_start_unchanged() {
    assert_eq!(add_business_days(19875, 0), 19875);
}

#[test]
fn friday_plus_one_skips_weekend() {
    assert_eq!(add_business_days(19874, 1), 19877);
}

#[test]
fn monday_plus_five_lands_next_monday() {
    assert_eq!(add_business_days(19870, 5), 19877);
}

#[test]
fn crosses_month_and_year_boundary() {
    assert_eq!(add_business_days(20084, 3), 20089);
}

#[test]
fn starting_on_a_weekend_still_counts_correctly() {
    assert_eq!(add_business_days(19875, 1), 19877);
}

