pub fn add_business_days(start_epoch_day: i64, n: i64) -> i64 {
    if n == 0 {
        return start_epoch_day;
    }
    let mut current = start_epoch_day;
    let mut counted = 0;
    while counted < n {
        current += 1;
        let weekday = (current + 3).rem_euclid(7);
        if weekday != 5 && weekday != 6 {
            counted += 1;
        }
    }
    current
}

