pub fn add_business_days(start_epoch_day: i64, n: i64) -> i64 {
    if n == 0 {
        return start_epoch_day;
    }
    let weeks = n / 5;
    let remainder = n % 5;
    let calendar_days = weeks * 7 + remainder;
    start_epoch_day + calendar_days
}
